candidates.raw:
    double n2;
    if ((sigma == NULL) || (shadow == NULL) || (switched == NULL)) {
        return ADCS_E_NULL;
    }
    if ((!isfinite(sigma->x)) || (!isfinite(sigma->y)) || (!isfinite(sigma->z))) {
        return ADCS_E_NOT_FINITE;
    }
    n2 = sigma->x * sigma->x + sigma->y * sigma->y + sigma->z * sigma->z;
    if (n2 > 1.0) {
        shadow->x = -sigma->x / n2;
        shadow->y = -sigma->y / n2;
        shadow->z = -sigma->z / n2;
        *switched = 1;
    } else {
        *shadow = *sigma;
        *switched = 0;
    }
    return ADCS_OK;
}

